"""Calculate only prospective bound widths from the frozen q1/support screen."""
from pathlib import Path
import pandas as pd,json
O=Path(__file__).resolve().parent
Q=pd.read_csv(O/'ROLE_SOURCE_WIDTH.csv');E=Q[Q.role.eq('event')].copy();assert len(E)==70 and E.positive_initial_denominator.all();assert E.unknown_weight_fraction.between(0,1).all()
V=E.groupby('review').agg(events=('event_id','size'),unsupported_initial_weight_fraction=('unknown_weight_fraction','mean'),events_wholly_unsupported=('unknown_weight_fraction',lambda x:int(x.ge(1-1e-12).sum()))).reset_index();V.to_csv(O/'REVIEW_SOURCE_WIDTH_EVENTS.csv',index=False)
S={'q2_quantities_read':False,'measure':'Prospective logical interval width, not a retention result or sampling confidence interval','original_event_population':70,'reviews':10,'event_role_positive_initial_denominator':70,'control_roles_with_exactly_zero_initial_new_cohort':int((~Q.positive_initial_denominator&Q.role.ne('event')).sum()),'control_zero_role_events':int(Q.loc[~Q.positive_initial_denominator&Q.role.ne('event'),'event_id'].nunique()),'event_only_equal_review_bound_width_pp':100*float(V.unsupported_initial_weight_fraction.mean()),'wholly_unsupported_events':int(E.unknown_weight_fraction.ge(1-1e-12).sum()),'partly_unsupported_events':int(E.unknown_weight_fraction.gt(0).sum()-E.unknown_weight_fraction.ge(1-1e-12).sum()),'fully_supported_events':int(E.unknown_weight_fraction.eq(0).sum()),'event_role_new_positions':int(E.new_positions.sum()),'supported_event_role_new_positions':int(E.supported_new_positions.sum()),'per_review':V.to_dict('records'),'aggregation':'equal event mean within review, then equal review mean; fund weights within event proportional to ORIGINAL q1 new-position capital','scope':'All original new-position fund IDs retained; unsupported cells have[0,q1] capacity. Original three peers remain in source ledger, but their44zero cohorts rule out an all70 stock-wise matched fraction.'}
(O/'EVENT_ONLY_SOURCE_PRECISION.json').write_text(json.dumps(S,indent=2)+'\n');print(json.dumps(S,indent=2))
